"use strict";
// Input: schemas generated by the pinned Codex binary, including --experimental.
const fs = require("node:fs");
const path = require("node:path");
const schemaRoot = path.resolve(process.argv[2]);
const version = process.argv[3];
if (!/^\d+\.\d+\.\d+$/.test(version || "")) throw new Error("Expected schema directory and runtime version");
const definitions = {};
function strip(value, schemaMap = false) {
  if (Array.isArray(value)) return value.map((child) => strip(child));
  if (!value || typeof value !== "object") return value;
  return Object.fromEntries(Object.entries(value)
    .filter(([key]) => schemaMap || !["title", "description", "default", "$schema"].includes(key))
    .map(([key, child]) => [key, strip(child, ["properties", "definitions", "patternProperties"].includes(key))]));
}
function read(name) {
  const { definitions: local = {}, ...schema } = strip(JSON.parse(fs.readFileSync(path.join(schemaRoot, name), "utf8")));
  Object.assign(definitions, local);
  return schema;
}
function methods(name) {
  return Object.fromEntries(read(name).oneOf.map((entry) => [entry.properties.method.enum[0], entry]));
}
const requests = methods("ClientRequest.json");
const notifications = methods("ServerNotification.json");
const serverRequests = methods("ServerRequest.json");
const responses = {};
for (const name of [
  "v1/InitializeResponse", "v2/LoginAccountResponse", "v2/GetAccountResponse", "v2/LogoutAccountResponse",
  "v2/ModelListResponse", "v2/GetAccountRateLimitsResponse", "v2/ThreadStartResponse", "v2/ThreadResumeResponse",
  "v2/TurnStartResponse", "v2/TurnSteerResponse", "v2/TurnInterruptResponse", "v2/SkillsListResponse",
  "v2/SkillsConfigWriteResponse", "v2/ListMcpServerStatusResponse", "v2/McpServerOauthLoginResponse",
  "CommandExecutionRequestApprovalResponse", "FileChangeRequestApprovalResponse",
  "PermissionsRequestApprovalResponse", "McpServerElicitationRequestResponse"
]) responses[name.split("/").pop()] = read(`${name}.json`);
const output = path.join(__dirname, "fixtures", "app-server", `${version}.json`);
fs.mkdirSync(path.dirname(output), { recursive: true });
fs.writeFileSync(output, JSON.stringify({ version, definitions, requests, notifications, serverRequests, responses }) + "\n");
console.log(`Exported ${version} protocol fixture: ${output}`);
